with deduped as (select id, customer_id, store_id, order_date, status, amount, discount, shipping_fee from (select *, row_number() over (partition by status order by order_date, id) as rn from orders) t where rn = 1) select status, date_trunc('month', order_date) as activity_month, percentile_approx(shipping_fee, array(0.25, 0.5, 0.75)) as shipping_fee_quartiles, stddev_samp(shipping_fee) as shipping_fee_stddev, sort_array(collect_set(status)) as status_list, grouping(status) as grouping_id from deduped group by cube (status, date_trunc('month', order_date)) order by status desc;
